<script lang="ts">import {onMount} from 'svelte';import Markdown from '../lib/Markdown.svelte';export let slug='';let room:any=null;let tab='quickstart';let ended=false;onMount(async()=>{const r=await fetch('/api/room/'+slug);room=await r.json();ended=room.ended;if(!ended){const events=new EventSource('/api/room/'+slug+'/events');events.addEventListener('session-ended',()=>{ended=true;events.close()})}});</script>
<main class="room" aria-live="polite">{#if room}{#if ended}<div class="ended"><h1>{room.game_title}</h1><p>This session has ended.</p><small>to-board</small></div>{:else}<header><h1>{room.game_title}</h1><span>to-board</span></header><nav><button class:active={tab==='quickstart'} on:click={()=>tab='quickstart'}>Quick-start Guide</button><button class:active={tab==='cheat'} on:click={()=>tab='cheat'}>Cheat Sheet</button></nav><article>{#if tab==='quickstart'}<Markdown value={room.quickstart_md}/>{:else}<Markdown value={room.cheat_sheet_md}/>{/if}</article>{/if}{/if}</main>
<style>.room{max-width:640px;margin:auto;padding:20px;background:#15141b;min-height:100vh}.room header{display:flex;justify-content:space-between;align-items:center}.room h1{font-size:24px}.room header span{color:#6d6d6d;font-size:12px}.room nav{display:flex;gap:24px;position:sticky;top:0;background:#15141b;border-bottom:1px solid #29263c}.room nav button{min-height:44px;background:transparent;color:#6d6d6d;border:0;border-bottom:2px solid transparent}.room nav button.active{color:#a277ff;border-color:#a277ff}.room article{padding:24px 0}.ended{display:grid;place-items:center;min-height:80vh;text-align:center}.ended small{color:#6d6d6d}</style>
